package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.exception.NullArgumentException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_subtract_TriageGen2Test {

    @Test
    public void testSubtract_NormalValues() {
        Complex c1 = new Complex(5.0, 3.0);
        Complex c2 = new Complex(2.0, 1.0);
        Complex expected = new Complex(3.0, 2.0);
        Complex result = c1.subtract(c2);
        assertEquals("Subtraction of normal complex numbers failed", expected, result);
    }

    @Test
    public void testSubtract_NegativeValues() {
        Complex c1 = new Complex(-1.0, -1.0);
        Complex c2 = new Complex(1.0, 1.0);
        Complex expected = new Complex(-2.0, -2.0);
        Complex result = c1.subtract(c2);
        assertEquals("Subtraction with negative numbers failed", expected, result);
    }

    @Test(expected = NullArgumentException.class)
    public void testSubtract_NullArgument() {
        Complex c1 = new Complex(1.0, 1.0);
        c1.subtract(null);
    }

    @Test
    public void testSubtract_ResultIsNaN_WhenLeftIsNaN() {
        Complex c1 = Complex.NaN;
        Complex c2 = new Complex(1.0, 1.0);
        Complex result = c1.subtract(c2);
        assertTrue("Result should be NaN if left operand is NaN", result.isNaN());
    }

    @Test
    public void testSubtract_ResultIsNaN_WhenRightIsNaN() {
        Complex c1 = new Complex(1.0, 1.0);
        Complex c2 = Complex.NaN;
        Complex result = c1.subtract(c2);
        assertTrue("Result should be NaN if right operand is NaN", result.isNaN());
    }

    @Test
    public void testSubtract_ResultIsNaN_WhenBothAreNaN() {
        Complex c1 = Complex.NaN;
        Complex c2 = Complex.NaN;
        Complex result = c1.subtract(c2);
        assertTrue("Result should be NaN if both operands are NaN", result.isNaN());
    }

    @Test
    public void testSubtract_ZeroValues() {
        Complex c1 = new Complex(0.0, 0.0);
        Complex c2 = new Complex(0.0, 0.0);
        Complex expected = new Complex(0.0, 0.0);
        Complex result = c1.subtract(c2);
        assertEquals("Subtraction of zeros failed", expected, result);
    }

    @Test
    public void testSubtract_Infinity() {
        Complex c1 = new Complex(Double.POSITIVE_INFINITY, 0.0);
        Complex c2 = new Complex(1.0, 0.0);
        Complex result = c1.subtract(c2);
        assertTrue("Result should be infinite", result.isInfinite());
        assertEquals(Double.POSITIVE_INFINITY, result.getReal(), 0.0);
    }
}
